/**
 * @typedef {{
 *  postMessage: (message: *, transfer?: Transferable[]) => void
 * }} Client
 */


// Auto-generated by .githooks/pre-commit (a content hash of every file this cache actually covers
// - index.html, css/**, js/**, static/**) - don't hand-edit this, it's overwritten on the next
// commit that touches any of those. See "Service worker caching" in CLAUDE.md for the one-time
// `npm install` setup that wires the hook up (frontend/package.json's "prepare" script).
const cacheVersion = 'v57887bb024a5';
const appCache = cacheVersion + '__' + 'app-cache';
const cacheWhitelist = [appCache];

// Dev-only escape hatch: flip to true and reload to bypass the cache entirely (every request goes
// straight to the network, nothing is read from or written to caches) - the code equivalent of
// devtools' Application > Service Workers > "Bypass for network", but persistent across tabs/
// restarts without having to remember to flip a devtools checkbox every session. Never commit this
// as true - it defeats the whole point of cache-first serving for real users.
const BYPASS_CACHE = false;

self.addEventListener('fetch', e =>
  // @ts-ignore
  e.respondWith(returnCachedFileOrFetchIt(e))
);


/**
 * Send message to clients
 * @param {*} msg
 * @param {Transferable[]} [transfer]
 */
function sendToClients(msg, transfer) {
  // @ts-ignore
  self.clients.matchAll()
    .then(
      /** @param {Client[]} clients */
      clients => {
        if (!clients || !clients.length) { console.info(' ** no clients'); }
        clients.forEach(c => c.postMessage({ msg, transfer }));
      })
    .catch(
      /** @param {Event} e */
      e => console.error(' ** @sendToClients', e)
    );
}

/** Install */
self.addEventListener('install', () => {
  console.info(' ** Install cache. Version:', cacheVersion);
  // @ts-ignore
  self.skipWaiting();
});

/** Activate */
self.addEventListener('activate', e => {
  console.info(' ** Activate cache. Version:', cacheVersion);
  // Without this, a brand new install doesn't take control of the page that triggered it - only
  // the *next* navigation would be. Cache-first serving only populates the cache as a side effect
  // of requests actually going through this SW, so a first-time visitor who goes offline before
  // ever reloading would find nothing cached at all. claim() lets initializeCache.js detect
  // control immediately; see its own comment for what it does with that.
  // @ts-ignore
  e.waitUntil(self.clients.claim());
  sendToClients({
    status: 'ACTIVATING',
    cacheWhitelist,
    cacheVersion,
  });
});

/** Focuses an already-open app window, or opens a new one, when a local notification is tapped */
self.addEventListener('notificationclick', event => {
  // @ts-ignore
  event.notification.close();
  // @ts-ignore
  event.waitUntil(
    // @ts-ignore
    self.clients.matchAll({ type: 'window', includeUncontrolled: true }).then(clientsList => {
      for (const client of clientsList) {
        if ('focus' in client) { return client.focus(); }
      }
      // @ts-ignore
      if (self.clients.openWindow) { return self.clients.openWindow('/'); }
    })
  );
});


/**
 * @param {Event} event
 */
async function returnCachedFileOrFetchIt(event) {
  try {
    // @ts-ignore
    /** @type {Request} */
    const request = event.request;
    const url = new URL(request.url);

    if (url.protocol === 'chrome-extension:') {
      return fetch(request);
    }

    // The Cache API's put() throws on anything but GET - not currently reachable (this app has no
    // non-GET fetches at all, no data API), but kept as defense-in-depth in case that ever changes.
    if (request.method !== 'GET') {
      return fetch(request);
    }

    if (BYPASS_CACHE) {
      return fetch(request);
    }

    return cacheFirst(request);
  } catch (e) {
    console.error('Error returning cached response', e);
  }
}

/**
 * @param {Request} request
 */
async function cacheFirst(request) {
  // @ts-ignore
  const cachedResponse = await caches.match(request);
  if (cachedResponse) {
    return cachedResponse;
  }
  // @ts-ignore
  const fetchResponse = await fetch(request);
  const cache = await caches.open(appCache);
  // @ts-ignore
  cache.put(request, fetchResponse.clone());
  return fetchResponse;
}
